/// Что открывает срок — ключ или пробный период (задача 93; условия, п. 4.4),
/// — строками списка «Что даёт ключ»: экран лицензии и ответ «Что будет без
/// ключа?» страницы «Купить» берут один список, и пункт, добавленный в одном
/// месте, не пропадёт в другом.
pub const LICENSE_WITH_TERM: [Key; 2] = [Key::LicenseWithTermIssue, Key::LicenseWithTermReport];

/// Что работает всегда, и без ключа (условия, п. 4.4 и 7), — так же одним
/// списком. Числа кварталов, кончившихся в срок, экран лицензии пишет с днём
/// конца срока (`LicenseAlwaysReportUntil`), когда срок известен.
pub const LICENSE_ALWAYS: [Key; 7] = [
    Key::LicenseAlwaysData,
    Key::LicenseAlwaysDrafts,
    Key::LicenseAlwaysMarks,
    Key::LicenseAlwaysTax,
    Key::LicenseAlwaysFiles,
    Key::LicenseAlwaysReport,
    Key::LicenseAlwaysUpdates,
];

/// Подставляет значения в шаблон вместо `{}`, по порядку.
///
/// Своя подстановка, а не `format!`: `format!` требует строку-литерал, а
/// шаблон приезжает из таблицы. Порядок мест — порядок `{}` в самом шаблоне,
/// и ради этого она и нужна: в армянском число и слово стоят иначе, чем
/// в русском, и склейка кусками на стороне вызова зашила бы русский порядок
/// слов во все три языка (опыт Savio).
///
/// Лишний `{}` остаётся в строке как есть: видимая дыра лучше молча
/// съеденного куска текста.
pub fn fill(template: &str, args: &[&str]) -> String {
    let mut out =
        String::with_capacity(template.len() + args.iter().map(|arg| arg.len()).sum::<usize>());
    let mut rest = template;
    let mut args = args.iter();
    while let Some(at) = rest.find("{}") {
        let Some(arg) = args.next() else {
            break;
        };
        out.push_str(&rest[..at]);
        out.push_str(arg);
        rest = &rest[at + 2..];
    }
    out.push_str(rest);
    out
}

/// Ошибка введённого числа — словами, с примером верной записи `example` на
/// языке `lang`. Одна на окно и калькулятор лендинга (задача 34): поле суммы
/// у них разбирает один [`parse_money`], и слова о его ошибке не должны
/// расходиться.
pub fn number_problem(lang: Lang, error: ParseError, example: &str) -> String {
    match error {
        ParseError::Empty => fill(t(lang, Key::NumberEmpty), &[example]),
        ParseError::Invalid => fill(t(lang, Key::NumberInvalid), &[example]),
        ParseError::Separators => fill(t(lang, Key::NumberSeparators), &[example]),
        ParseError::TooPrecise { max: 0 } => fill(t(lang, Key::NumberWhole), &[example]),
        ParseError::TooPrecise { max } => {
            fill(t(lang, Key::NumberTooPrecise), &[&integer(lang, i64::from(max)), example])
        }
        ParseError::TooLarge => t(lang, Key::NumberTooLarge).to_owned(),
    }
}

/// Форма слова при числительном.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Plural {
    One,
    Few,
    Many,
}

/// Какая форма слова нужна при числе `n`.
///
/// Русскому нужны три: «1 счёт, 2 счёта, 5 счетов», и одиннадцать —
/// четырнадцать — исключение: «11 счетов», «112 счетов». Правило совпадает
/// с CLDR 48 на всех числах от 0 до 2000 (сверено с `Intl.PluralRules`
/// 2026-10-11). Английскому нужны две, `Few` у него не бывает.
///
/// Армянскому — одна: при числительном существительное остаётся
/// в единственном числе, «5 հաշիվ» (решение человека 2026-10-11, как
/// в Arpa и Savio). У CLDR для армянского две категории — `one` для 0 и 1
/// и `other`, — но форму существительного при числе они не меняют.
const fn plural_form(lang: Lang, n: u64) -> Plural {
    match lang {
        Lang::Ru => {
            if n % 100 >= 11 && n % 100 <= 14 {
                Plural::Many
            } else {
                match n % 10 {
                    1 => Plural::One,
                    2..=4 => Plural::Few,
                    _ => Plural::Many,
                }
            }
        }
        Lang::En => {
            if n == 1 {
                Plural::One
            } else {
                Plural::Many
            }
        }
        Lang::Am => Plural::One,
    }
}

/// Форма слова при числе `n` из ключей `…One`, `…Few`, `…Many`.
///
/// Ключей всегда три, потому что их требует русский. В английском переводе
/// `…Few` повторяет `…Many`, а в армянском все три одинаковы — это правило
/// языка, а не упрощение. Само число записывает [`integer`]: «1 000 счетов»,
/// а не «1000 счетов».
pub const fn plural(lang: Lang, n: u64, one: Key, few: Key, many: Key) -> &'static str {
    let key = match plural_form(lang, n) {
        Plural::One => one,
        Plural::Few => few,
        Plural::Many => many,
    };
    t(lang, key)
}

/// Что не так с записью текста на языке `lang`; `None` — всё так. Правила
/// одни у таблицы строк (тест ниже) и у заметок «Что нового»
/// (`crates/app/tests/notes.rs`, задача 67): их читает тот же человек, а
/// пишут их так же — копированием русской строки. Открыта, как
/// [`ALL_KEYS`], ради теста другого крейта; в wasm окна её нет, пока её
/// никто не зовёт.
///
/// - Ни пробелов подряд, ни пробела по краям — признака потерянного
///   переноса строки в исходнике (опыт Savio).
/// - Тире не начинает строку: перед ним неразрывный пробел (U+00A0).
///   С обычным перенос оставляет «— при его закрытии» в начале строки — на
///   телефоне это видно сразу (глазной прогон задачи 6).
/// - Кавычки принадлежат языку, а не строке (Правило 4): «ёлочки» —
///   в русском и армянском, “лапки” — в английском. Кавычки внутри кавычек
///   в русском — „немецкие“: открывает их U+201E, а закрывает U+201C — та
///   же, что открывает английские. Поэтому пара „…“ своя, а “ без „ перед
///   ней — английская.
/// - Ни буквы кириллицы в английском и армянском: так выглядит скопированная
///   и переведённая не целиком русская строка (опыт Arpa).
/// - Армянский определённый артикль перед словом на гласный звук — «ն»,
///   а не «ը»: «տեսակն ակտում», а не «տեսակը ակտում» (задача 81). Гласный
///   звук в начале слова — «ա», «է», «ը», «ի», «օ» и «ու»; «ե», «ո» и «և»
///   там звучат [йе], [во] и [йев], и перед ними «ը» остаётся: «ծրագիրը
///   երկար», «օրը ոչ», «էջը և» (решение человека 2026-10-23). После
///   запятой и другой паузы «ը» остаётся тоже: правило — для слов подряд
///   через пробел.
pub fn flaw(lang: Lang, text: &str) -> Option<&'static str> {
    if text.contains("  ") || text.starts_with(' ') || text.ends_with(' ') {
        return Some("пробелы подряд или по краям");
    }
    if text.contains(" —") || text.starts_with('—') {
        return Some("тире после обычного пробела");
    }
    let foreign_quotes = match lang {
        Lang::En => text.contains(['«', '»', '„']),
        Lang::Ru | Lang::Am => {
            let mut nested = false;
            let english = text.chars().any(|c| match c {
                '„' if !nested => {
                    nested = true;
                    false
                }
                '“' if nested => {
                    nested = false;
                    false
                }
                '„' | '“' | '”' => true,
                _ => false,
            });
            english || nested
        }
    };
    if foreign_quotes {
        return Some("кавычки не того языка");
    }
    let cyrillic = |c: char| ('\u{400}'..='\u{4FF}').contains(&c);
    if matches!(lang, Lang::En | Lang::Am) && text.chars().any(cyrillic) {
        return Some("кириллица в переводе");
    }
    let vowel_first = |word: &str| {
        word.starts_with(['ա', 'է', 'ը', 'ի', 'օ', 'Ա', 'Է', 'Ը', 'Ի', 'Օ'])
            || word.starts_with("ու")
            || word.starts_with("Ու")
            || word.starts_with("ՈՒ")
    };
    let words = || text.split(' ');
    if lang == Lang::Am
        && words()
            .zip(words().skip(1))
            .any(|(word, next)| word.ends_with('ը') && vowel_first(next))
    {
        return Some("«ը» перед гласной: нужно «ն»");
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Пустая подпись в окне выглядит поломкой, а не пропущенным переводом,
    /// и найти её можно только глазами и только на том языке, где её забыли.
    #[test]
    fn every_key_says_something_in_every_language() {
        let mut empty = Vec::new();
        for (key, name) in ALL_KEYS {
            for lang in Lang::ALL {
                if t(lang, *key).trim().is_empty() {
                    empty.push(format!("{name} ({lang:?})"));
                }
            }
        }
        assert!(empty.is_empty(), "пустые строки: {empty:?}");
    }

    /// Каждая строка таблицы записана по правилам своего языка ([`flaw`]):
    /// пробелы, тире, кавычки, кириллица в переводе.
    #[test]
    fn every_string_follows_its_language() {
        let mut wrong = Vec::new();
        for (key, name) in ALL_KEYS {
            for lang in Lang::ALL {
                let text = t(lang, *key);
                if let Some(flaw) = flaw(lang, text) {
                    wrong.push(format!("{name} ({lang:?}): {flaw} — «{text}»"));
                }
            }
        }
        assert!(wrong.is_empty(), "строки не по правилам языка: {wrong:#?}");
    }

    /// Сами правила [`flaw`] — на образцах: таблица сейчас чиста, и без
    /// образцов сломанное правило прошло бы незамеченным.
    #[test]
    fn flaw_knows_each_rule() {
        let mut wrong = Vec::new();
        for (lang, text, flawed) in [
            (Lang::Ru, "Счёт сохранён.", false),
            (Lang::Ru, "Счёт  сохранён.", true),
            (Lang::Ru, " Счёт", true),
            (Lang::En, "Saved ", true),
            (Lang::Ru, "Целы\u{A0}— перезагрузите", false),
            (Lang::Ru, "Целы — перезагрузите", true),
            (Lang::Am, "— Ոչ", true),
            (Lang::Ru, "Кнопка «Сохранить»", false),
            (Lang::Ru, "Кнопка «Акт „по счёту“»", false),
            (Lang::Ru, "Кнопка “Сохранить”", true),
            (Lang::Ru, "Кнопка „Сохранить", true),
            (Lang::Am, "Կոճակ «Պահպանել»", false),
            (Lang::Am, "Կոճակ “Պահպանել”", true),
            (Lang::En, "The “Save” button", false),
            (Lang::En, "The «Save» button", true),
            (Lang::En, "The „Save“ button", true),
            (Lang::En, "Save счёт", true),
            (Lang::Am, "Պահպանել счёт", true),
            (Lang::Am, "Նշեք տեսակն ակտում", false),
            (Lang::Am, "Նշեք տեսակը ակտում", true),
            (Lang::Am, "{}-ը ամբողջությամբ", true),
            (Lang::Am, "Եկամուտը իր", true),
            (Lang::Am, "ամիսը օրենքը", true),
            (Lang::Am, "օրը ընկած", true),
            (Lang::Am, "գիրքը էջում", true),
            (Lang::Am, "գիրքը ու գրիչը", true),
            (Lang::Am, "ամիսը Օգոստոս", true),
            (Lang::Am, "ծրագիրը երկար", false),
            (Lang::Am, "օրը ոչ", false),
            (Lang::Am, "էջը և", false),
            (Lang::Am, "տեսակը, ակտում", false),
            (Lang::Am, "տեսակը\u{A0}— ակտում", false),
            (Lang::Ru, "Счёт ը ա", false),
        ] {
            if flaw(lang, text).is_some() != flawed {
                wrong.push(format!("{lang:?} «{text}»: {:?}", flaw(lang, text)));
            }
        }
        assert!(wrong.is_empty(), "правила записи: {wrong:#?}");
    }

    /// У шаблона одинаковое число мест во всех трёх языках: потерянное `{}` —
    /// молча пропавшее число, лишнее — видимые «{}» в окне.
    #[test]
    fn a_template_keeps_its_placeholders_in_every_language() {
        let mut wrong = Vec::new();
        for (key, name) in ALL_KEYS {
            let places = |lang| t(lang, *key).matches("{}").count();
            let ru = places(Lang::Ru);
            for lang in [Lang::En, Lang::Am] {
                if places(lang) != ru {
                    wrong.push(format!(
                        "{name} ({lang:?}): мест {}, в русском {ru}",
                        places(lang)
                    ));
                }
            }
        }
        assert!(wrong.is_empty(), "места в шаблонах разошлись: {wrong:#?}");
    }

    /// Код армянского — `hy`, а не `am` (амхарский), и каждый код читается
    /// обратно в тот же язык: иначе запомненный выбор не переживёт
    /// перезапуска.
    #[test]
    fn codes_are_iso_and_round_trip() {
        let codes: Vec<&str> = Lang::ALL.iter().map(|lang| lang.code()).collect();
        assert_eq!(codes, ["hy", "ru", "en"]);

        let mut lost = Vec::new();
        for lang in Lang::ALL {
            if Lang::from_code(lang.code()) != Some(lang) {
                lost.push(lang);
            }
        }
        assert!(lost.is_empty(), "код не читается обратно: {lost:?}");
        assert_eq!(Lang::from_code("am"), None);
    }

    /// В данных язык — код, а не имя варианта: `Am` записался бы `"Am"`,
    /// а это амхарский.
    #[test]
    fn data_keeps_the_code() {
        let written: Vec<String> = Lang::ALL
            .iter()
            .filter_map(|lang| serde_json::to_string(lang).ok())
            .collect();
        assert_eq!(written, [r#""hy""#, r#""ru""#, r#""en""#]);
        assert_eq!(serde_json::from_str::<Lang>(r#""hy""#).ok(), Some(Lang::Am));
        for json in [r#""am""#, r#""Am""#, r#""HY""#, r#""hy-AM""#, r#""""#, "0"] {
            assert!(serde_json::from_str::<Lang>(json).is_err(), "{json} прочитан");
        }
    }

    /// Язык при первом заходе — первый знакомый из языков браузера, а не
    /// первый язык списка и не язык с регионом целиком. Ожидаемое выписано
    /// человеком по смыслу случаев.
    #[test]
    fn first_language_follows_the_browser() {
        let cases: [(&[&str], Lang); 11] = [
            (&["ru-RU", "ru", "en-US"], Lang::Ru),
            (&["hy-AM"], Lang::Am),
            (&["en-GB", "ru"], Lang::En),
            (&["de-DE", "fr", "ru-RU"], Lang::Ru),
            (&["de-DE", "fr"], Lang::Am),
            (&[], Lang::Am),
            (&["RU"], Lang::Ru),
            (&["en_US"], Lang::En),
            (&["hy-arevmda"], Lang::Am),
            (&["am-ET", "en"], Lang::En),
            (&["", "rus", "ru"], Lang::Ru),
        ];
        let mut wrong = Vec::new();
        for (tags, expected) in cases {
            let got = Lang::preferred(tags.iter().copied());
            if got != expected {
                wrong.push(format!("{tags:?}: {got:?}, а не {expected:?}"));
            }
        }
        assert!(wrong.is_empty(), "не тот язык при первом заходе: {wrong:#?}");
    }

    #[test]
    fn fill_puts_values_where_the_template_asks() {
        assert_eq!(fill("{} из {}", &["5", "10"]), "5 из 10");
        assert_eq!(fill("без мест", &["5"]), "без мест");
        assert_eq!(fill("{} и {}", &["раз"]), "раз и {}");
        assert_eq!(fill("{}", &["раз", "два"]), "раз");
        assert_eq!(fill("Քայլ {}՝ {}-ից", &["2", "3"]), "Քայլ 2՝ 3-ից");
    }

    /// Формы выписаны человеком по грамматике, а не той же формулой. Русские
    /// числа — те, на которых правило ошибается проще всего: 11–14 и 111–114
    /// исключение, а 21, 101 и 1001 — снова «один».
    #[test]
    fn plural_follows_each_language_rules() {
        use Plural::{Few, Many, One};
        let mut cases = vec![
            (Lang::Ru, 0, Many),
            (Lang::Ru, 1, One),
            (Lang::Ru, 2, Few),
            (Lang::Ru, 4, Few),
            (Lang::Ru, 5, Many),
            (Lang::Ru, 10, Many),
            (Lang::Ru, 11, Many),
            (Lang::Ru, 12, Many),
            (Lang::Ru, 14, Many),
            (Lang::Ru, 15, Many),
            (Lang::Ru, 21, One),
            (Lang::Ru, 22, Few),
            (Lang::Ru, 25, Many),
            (Lang::Ru, 101, One),
            (Lang::Ru, 111, Many),
            (Lang::Ru, 112, Many),
            (Lang::Ru, 122, Few),
            (Lang::Ru, 1_001, One),
            (Lang::Ru, 1_011, Many),
            (Lang::En, 0, Many),
            (Lang::En, 1, One),
            (Lang::En, 2, Many),
            (Lang::En, 21, Many),
            (Lang::En, 101, Many),
        ];
        for n in [0, 1, 2, 5, 11, 21, 1_000] {
            cases.push((Lang::Am, n, One));
        }
        let mut wrong = Vec::new();
        for (lang, n, expected) in cases {
            let got = plural_form(lang, n);
            if got != expected {
                wrong.push(format!("{lang:?} {n}: {got:?}, а не {expected:?}"));
            }
        }
        assert!(wrong.is_empty(), "не та форма слова: {wrong:#?}");
    }
}
